
use rtrb::RingBuffer;
use std::{cell::RefCell,rc::Rc,panic::{catch_unwind,AssertUnwindSafe}};
#[derive(Debug)]struct T{id:usize,heap:String,d:Rc<RefCell<Vec<usize>>>,bomb:Rc<RefCell<Option<usize>>>}
impl Drop for T{fn drop(&mut self){self.d.borrow_mut()[self.id]+=1;let fire=*self.bomb.borrow()==Some(self.id);if fire{*self.bomb.borrow_mut()=None;panic!("injected destructor panic");}}}
fn item(id:usize,d:&Rc<RefCell<Vec<usize>>>,b:&Rc<RefCell<Option<usize>>>)->T{T{id,heap:format!("item{id}"),d:d.clone(),bomb:b.clone()}}
fn fill(wrapped:bool,d:&Rc<RefCell<Vec<usize>>>,b:&Rc<RefCell<Option<usize>>>)->(rtrb::Producer<T>,rtrb::Consumer<T>){let(mut p,mut c)=RingBuffer::new(4);for id in 0..4{p.push(item(id,d,b)).unwrap();}if wrapped{drop(c.pop().unwrap());drop(c.pop().unwrap());for id in 4..6{p.push(item(id,d,b)).unwrap();}}(p,c)}
fn main(){for wrapped in [false,true]{for all in [false,true]{for offset in 0..4{let d=Rc::new(RefCell::new(vec![0;16]));let b=Rc::new(RefCell::new(None));let(p,mut c)=fill(wrapped,&d,&b);let start=if wrapped{2}else{0};*b.borrow_mut()=Some(start+offset);let r=catch_unwind(AssertUnwindSafe(||{let chunk=c.read_chunk(4).unwrap();if all{chunk.commit_all()}else{chunk.commit(offset+1)}}));assert!(r.is_err());*b.borrow_mut()=None;let mut seen=vec![];while let Ok(t)=c.pop(){assert_eq!(d.borrow()[t.id],0);assert_eq!(t.heap,format!("item{}",t.id));assert!(!seen.contains(&t.id));seen.push(t.id);}drop(c);drop(p);assert!(d.borrow().iter().all(|&x|x<=1));}}}let d=Rc::new(RefCell::new(vec![0;16]));let b=Rc::new(RefCell::new(None));let(p,mut c)=fill(true,&d,&b);let r=catch_unwind(AssertUnwindSafe(||c.read_chunk(4).unwrap().commit(5)));assert!(r.is_err());assert_eq!(c.slots(),4);c.read_chunk(4).unwrap().commit_all();assert_eq!(c.slots(),0);drop(c);drop(p);for id in 0..6{assert_eq!(d.borrow()[id],1);}}
